import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { getMatchId } from "../api";

// --- ВСПОМОГАТЕЛЬНЫЕ КОМПОНЕНТЫ ---

const ResultCircle = ({ res }) => {
  const colors = { W: "bg-green-500", D: "bg-yellow-500", L: "bg-red-600" };
  return (
    <span
      className={`${colors[res]} w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-black text-white shadow-lg`}
    >
      {res}
    </span>
  );
};

const StatBar = ({ label, h, a, reverse, color }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = (parseFloat(h) || 0) + (parseFloat(a) || 0) || 1;
  return (
    <div className="relative group">
      <div className="flex justify-between items-end mb-2">
        <span className="text-2xl font-black text-white">
          {(parseFloat(h) || 0).toFixed(2)}
        </span>
        <span className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest mb-1 text-center">
          {label}
        </span>
        <span className="text-2xl font-black text-white">
          {(parseFloat(a) || 0).toFixed(2)}
        </span>
      </div>
      <div className="h-2.5 w-full bg-gray-800 rounded-full flex overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-1000 ${isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${((parseFloat(h) || 0) / total) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-1000 ${!isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${((parseFloat(a) || 0) / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

const HistoryList = ({ title, matches }) => (
  <div className="bg-gray-800/40 p-6 md:p-8 rounded-[32px] border border-white/5 h-full shadow-xl">
    <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-6 text-center">
      {title}
    </h3>
    <div className="space-y-4">
      {matches && matches.length > 0 ? (
        matches.map((m, i) => (
          <div
            key={i}
            className="flex items-center justify-between gap-4 bg-black/20 p-4 rounded-2xl border border-white/5"
          >
            <div
              className={`text-[9px] font-black px-2.5 py-1 rounded-lg uppercase tracking-widest border ${
                m.is_home
                  ? "bg-blue-500/10 text-blue-400 border-blue-500/20"
                  : "bg-purple-500/10 text-purple-400 border-purple-500/20"
              }`}
            >
              {m.is_home ? "ДОМА" : "ГОСТИ"}
            </div>
            <div className="flex items-center gap-3 flex-grow min-w-0">
              <img
                src={m.opponent_logo}
                alt=""
                className="w-8 h-8 object-contain"
              />
              <span className="text-sm font-bold text-white truncate">
                {m.opponent}
              </span>
            </div>
            <div className="flex items-center gap-3">
              <span className="text-sm font-black text-white font-mono">
                {m.score}
              </span>
              <span
                className={`w-7 h-7 rounded-lg flex items-center justify-center text-[10px] font-black ${
                  m.res === "W"
                    ? "bg-green-500 text-white"
                    : m.res === "L"
                      ? "bg-red-600 text-white"
                      : "bg-yellow-500 text-black"
                }`}
              >
                {m.res}
              </span>
            </div>
          </div>
        ))
      ) : (
        <p className="text-xs text-gray-600 text-center py-4 italic">
          Нет данных
        </p>
      )}
    </div>
  </div>
);

// --- ОСНОВНОЙ КОМПОНЕНТ ---

function MatchDetailPage() {
  const { matchId } = useParams();
  const [match, setMatch] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const mData = await getMatchId(matchId);
      setMatch(mData);
      setLoading(false);
    };
    fetchData();
  }, [matchId]);

  if (loading)
    return (
      <div className="h-screen flex items-center justify-center bg-gray-950 text-white font-black tracking-[0.3em] uppercase animate-pulse">
        Анализ матча...
      </div>
    );
  if (!match)
    return (
      <div className="text-center p-20 text-white font-black uppercase">
        Матч не найден
      </div>
    );

  const predStyle = match.prediction
    ? match.prediction.outcome === "Win Home"
      ? { text: "Победа П1", color: "text-green-500" }
      : match.prediction.outcome === "Win Away"
        ? { text: "Победа П2", color: "text-red-600" }
        : { text: "Ничья (X)", color: "text-yellow-500" }
    : null;

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 text-white font-sans">
      {/* 1. ШАПКА МАТЧА */}
      <div className="flex flex-col md:flex-row justify-between items-center bg-gray-900 p-8 md:p-12 rounded-[32px] border border-gray-800 shadow-2xl relative overflow-hidden mb-10">
        <div className="flex flex-col items-center w-full md:w-2/5">
          <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-4 py-1.5 rounded-full mb-4 tracking-widest border border-gray-700">
            ELO: {Math.round(match.homeTeam.elo)}
          </div>
          <img
            src={match.homeTeam.logo_url}
            className="h-28 w-28 md:h-40 md:w-40 object-contain mb-4 drop-shadow-2xl"
            alt=""
          />
          <h1 className="text-2xl md:text-3xl font-black uppercase tracking-tighter text-center">
            {match.homeTeam.name_ru || match.homeTeam.name}
          </h1>
          <div className="flex gap-1.5 mt-4">
            {match.homeTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>

        <div className="flex flex-col items-center my-8 md:my-0">
          <span className="text-5xl md:text-6xl font-black text-white opacity-20 italic mb-4 uppercase">
            VS
          </span>
          {match.status === "FINISHED" ? (
            <div className="text-4xl font-black text-white bg-white/10 px-6 py-2 rounded-2xl border border-white/20">
              {match.score.home} : {match.score.away}
            </div>
          ) : (
            <div className="text-center">
              <div className="text-sm font-bold text-white tracking-widest uppercase mb-1">
                {new Date(match.utcDate).toLocaleDateString("ru-RU", {
                  day: "2-digit",
                  month: "2-digit",
                })}
              </div>
              <div className="text-3xl font-black text-white">
                {new Date(match.utcDate).toLocaleTimeString([], {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </div>
            </div>
          )}
        </div>

        <div className="flex flex-col items-center w-full md:w-2/5">
          <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-4 py-1.5 rounded-full mb-4 tracking-widest border border-gray-700">
            ELO: {Math.round(match.awayTeam.elo)}
          </div>
          <img
            src={match.awayTeam.logo_url}
            className="h-28 w-28 md:h-40 md:w-40 object-contain mb-4 drop-shadow-2xl"
            alt=""
          />
          <h1 className="text-2xl md:text-3xl font-black uppercase tracking-tighter text-center">
            {match.awayTeam.name_ru || match.awayTeam.name}
          </h1>
          <div className="flex gap-1.5 mt-4">
            {match.awayTeam.stats_last_5.form.map((r, i) => (
              <ResultCircle key={i} res={r} />
            ))}
          </div>
        </div>
      </div>

      {/* 2. ПРОГНОЗ */}
      {match.prediction && (
        <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 mb-10 border border-gray-800 shadow-2xl relative overflow-hidden">
          <h2 className="text-sm md:text-base font-black text-white uppercase tracking-[0.3em] mb-10 text-center">
            Прогноз Нейросети
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-stretch relative z-10">
            <div className="bg-black/40 p-6 rounded-3xl border border-gray-800 flex flex-col justify-center">
              <div className="flex justify-between mb-3 text-xs md:text-sm font-black uppercase tracking-widest text-white">
                <span>П1: {match.prediction.prob_home}%</span>
                <span>X: {match.prediction.prob_draw}%</span>
                <span>П2: {match.prediction.prob_away}%</span>
              </div>
              <div className="h-5 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700 shadow-inner">
                <div
                  className="bg-green-500 h-full rounded-l-full"
                  style={{ width: `${match.prediction.prob_home}%` }}
                ></div>
                <div
                  className="bg-yellow-500 h-full"
                  style={{ width: `${match.prediction.prob_draw}%` }}
                ></div>
                <div
                  className="bg-red-600 h-full rounded-r-full"
                  style={{ width: `${match.prediction.prob_away}%` }}
                ></div>
              </div>
            </div>

            <div className="flex flex-col items-center justify-center p-6 bg-gray-800/30 rounded-3xl border border-gray-800 text-center">
              <span
                className={`text-xl md:text-2xl font-black uppercase tracking-widest mb-4 ${predStyle.color}`}
              >
                {predStyle.text}
              </span>
              <span className="text-[10px] font-black text-white opacity-40 uppercase tracking-widest mb-2">
                Вероятный счет
              </span>
              <span className="text-6xl font-black text-white italic tracking-tighter">
                {match.prediction.exact_score}
              </span>
            </div>

            <div className="bg-black/40 p-6 rounded-3xl border border-gray-800 flex flex-col justify-center">
              <div className="flex justify-between mb-3 text-xs md:text-sm font-black uppercase tracking-widest text-white">
                <span>БОЛЬШЕ: {match.prediction.total_over_2_5}%</span>
                <span>
                  МЕНЬШЕ: {(100 - match.prediction.total_over_2_5).toFixed(1)}%
                </span>
              </div>
              <div className="h-5 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700 shadow-inner">
                <div
                  className="bg-red-600 h-full rounded-l-full shadow-[0_0_10px_red]"
                  style={{ width: `${match.prediction.total_over_2_5}%` }}
                ></div>
                <div
                  className="bg-yellow-500 h-full rounded-r-full"
                  style={{
                    width: `${(100 - match.prediction.total_over_2_5).toFixed(1)}%`,
                  }}
                ></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 3. СТАТИСТИКА */}
      <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 border border-gray-800 shadow-xl mb-10">
        <h2 className="text-sm font-black text-white uppercase tracking-[0.3em] mb-12 text-center">
          Глубокий анализ (Last 5)
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-20">
          <div className="space-y-8">
            <div className="text-center mb-6">
              <span className="inline-block bg-green-500/10 border border-green-500/30 text-green-500 text-[11px] font-black uppercase tracking-widest px-6 py-2 rounded-full">
                Атакующий потенциал
              </span>
            </div>
            <StatBar
              label="В среднем забито"
              h={match.homeTeam.stats_last_5.gf}
              a={match.awayTeam.stats_last_5.gf}
              color="bg-green-500"
            />
            <StatBar
              label="Созданный xG"
              h={match.homeTeam.stats_last_5.xg_for}
              a={match.awayTeam.stats_last_5.xg_for}
              color="bg-green-500"
            />
            <StatBar
              label="Глубокие атаки"
              h={match.homeTeam.stats_last_5.deep}
              a={match.awayTeam.stats_last_5.deep}
              color="bg-green-500"
            />
          </div>
          <div className="space-y-8">
            <div className="text-center mb-6">
              <span className="inline-block bg-red-600/10 border border-red-600/30 text-red-500 text-[11px] font-black uppercase tracking-widest px-6 py-2 rounded-full">
                Надежность обороны
              </span>
            </div>
            <StatBar
              label="В среднем пропущено"
              h={match.homeTeam.stats_last_5.ga}
              a={match.awayTeam.stats_last_5.ga}
              reverse
              color="bg-red-600"
            />
            <StatBar
              label="Допущенный xG"
              h={match.homeTeam.stats_last_5.xg_against}
              a={match.awayTeam.stats_last_5.xg_against}
              reverse
              color="bg-red-600"
            />
            <StatBar
              label="Прессинг (PPDA)"
              h={match.homeTeam.stats_last_5.ppda}
              a={match.awayTeam.stats_last_5.ppda}
              reverse
              color="bg-red-600"
            />
          </div>
        </div>
      </div>

      {/* 4. ПОСЛЕДНИЕ МАТЧИ (ОДНОЙ СТРОКОЙ) */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
        <HistoryList
          title={`Последние игры: ${match.homeTeam.name_ru || match.homeTeam.name}`}
          matches={match.homeTeam.history}
        />
        <HistoryList
          title={`Последние игры: ${match.awayTeam.name_ru || match.awayTeam.name}`}
          matches={match.awayTeam.history}
        />
      </div>

      {/* 5. ЛИЧНЫЕ ВСТРЕЧИ (ОТДЕЛЬНЫМ БЛОКОМ СНИЗУ) */}
      <div className="bg-gray-900/80 p-8 rounded-[32px] border border-red-600/20 shadow-2xl">
        <h3 className="text-xs font-black text-red-600 uppercase tracking-[0.4em] mb-8 text-center">
          Очные встречи (H2H)
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {match.h2h && match.h2h.length > 0 ? (
            match.h2h.map((m, i) => (
              <div
                key={i}
                className="bg-black/20 p-6 rounded-2xl border border-white/5 text-center"
              >
                <div className="text-[10px] font-bold text-gray-500 mb-3 tracking-widest uppercase">
                  {m.date}
                </div>
                <div className="flex flex-col gap-2">
                  <span className="text-xs font-black text-white uppercase truncate">
                    {m.home}
                  </span>
                  <span className="text-2xl font-black text-red-600 italic leading-none">
                    {m.score}
                  </span>
                  <span className="text-xs font-black text-white uppercase truncate">
                    {m.away}
                  </span>
                </div>
              </div>
            ))
          ) : (
            <p className="col-span-3 text-sm text-gray-600 italic text-center py-6">
              История встреч не найдена
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

export default MatchDetailPage;
